"ids": ["brevieres", "le-lac", "val-claret", "grande-motte", "la-daille", "val-disere", "solaise", "le-fornet"], "easy": {"brevieres": {"le-lac": 1, "val-claret": 2, "grande-motte": 3, "la-daille": 2, "val-disere": 3, "solaise": 5, "le-fornet": 7}, "le-lac": {"brevieres": 1, "val-claret": 1, "grande-motte": 2, "la-daille": 1, "val-disere": 2, "solaise": 4, "le-fornet": 6}, "val-claret": {"brevieres": 3, "le-lac": 1, "grande-motte": 1, "la-daille": 1, "val-disere": 2, "solaise": 4, "le-fornet": 6}, "grande-motte": {"brevieres": 3, "le-lac": 2, "val-claret": 0, "la-daille": 1, "val-disere": 2, "solaise": 4, "le-fornet": 6}, "la-daille": {"brevieres": 3, "le-lac": 2, "val-claret": 1, "grande-motte": 2, "val-disere": 1, "solaise": 3, "le-fornet": 5}, "val-disere": {"brevieres": 4, "le-lac": 3, "val-claret": 2, "grande-motte": 3, "la-daille": 1, "solaise": 1, "le-fornet": 1}, "solaise": {"brevieres": 6, "le-lac": 5, "val-claret": 4, "grande-motte": 5, "la-daille": 3, "val-disere": 2, "le-fornet": 1}, "le-fornet": {"brevieres": 8, "le-lac": 7, "val-claret": 6, "grande-motte": 7, "la-daille": 5, "val-disere": 4, "solaise": 1}}, "red": {"brevieres": {"le-lac": 1, "val-claret": 2, "grande-motte": 3, "la-daille": 2, "val-disere": 3, "solaise": 4, "le-fornet": 5}, "le-lac": {"brevieres": 1, "val-claret": 1, "grande-motte": 2, "la-daille": 1, "val-disere": 2, "solaise": 3, "le-fornet": 4}, "val-claret": {"brevieres": 3, "le-lac": 1, "grande-motte": 1, "la-daille": 1, "val-disere": 2, "solaise": 3, "le-fornet": 4}, "grande-motte": {"brevieres": 3, "le-lac": 2, "val-claret": 0, "la-daille": 1, "val-disere": 2, "solaise": 3, "le-fornet": 4}, "la-daille": {"brevieres": 3, "le-lac": 2, "val-claret": 1, "grande-motte": 2, "val-disere": 1, "solaise": 2, "le-fornet": 3}, "val-disere": {"brevieres": 4, "le-lac": 3, "val-claret": 2, "grande-motte": 3, "la-daille": 1, "solaise": 1, "le-fornet": 1}, "solaise": {"brevieres": 5, "le-lac": 4, "val-claret": 3, "grande-motte": 4, "la-daille": 2