insert into content.content_block (place_id,section,slot,ord,body,fact_refs,status,author,field) values
('area:tignes-val-disere','meta','line',0,'Tignes Val d''Isère | Linked ski areas | Snow Catchers','{}'::text[],'review','loader','title'),
('area:tignes-val-disere','meta','line',1,'How Tignes and Val d''Isère fit together across the Tovière and Bellevarde ridge, which base reaches which side, how the snow changes with height, what the single area pass costs, and what the area is like for boarders, families, food and evenings.','{}'::text[],'review','loader','description'),
('area:tignes-val-disere','meta','line',2,'France','{}'::text[],'review','loader','crumbs.0.label'),
('area:tignes-val-disere','meta','line',3,'Linked ski areas','{}'::text[],'review','loader','crumbs.1.label'),
('area:tignes-val-disere','meta','line',4,'Northern Alps','{}'::text[],'review','loader','crumbs.2.label'),
('area:tignes-val-disere','hero','lead',0,'Tignes and Val d''Isère share the head of the Isère valley, joined over the ridge of Tovière and Bellevarde into one area that the operator puts at {{f:F000373}} of piste. Its lifts climb from Les Brévières at {{f:F000382}} to the Grande Motte cable car at {{f:F000381}}. Tignes was built for skiing after its old village vanished under the Chevril reservoir in {{f:F000386}}, and in {{f:F000388}} Val d''Isère staged the Olympic men''s downhill on the Face de Bellevarde.',array['F000373','F000381','F000382','F000386','F000388']::text[],'review','loader','hero.lead'),
('area:tignes-val-disere','stats','line',0,'{{f:F000080}}',array['F000080']::text[],'review','loader','stats.0.v'),
('area:tignes-val-disere','stats','line',1,'of linked piste on skiresort.com, the same as the operator''s count','{}'::text[],'review','loader','stats.0.t'),
('area:tignes-val-disere','stats','line',2,'{{f:F000082|n}} to {{f:F000083}}',array['F000082','F000083']::text[],'review','loader','stats.1.v'),
('area:tignes-val-disere','stats','line',3,'from Les Brévières to the top of the Grande Motte cable car, on skiresort.com','{}'::text[],'review','loader','stats.1.t'),
('area:tignes-val-disere','stats','line',4,'{{f:F000086}}',array['F000086']::text[],'review','loader','stats.2.v'),
('area:tignes-val-disere','stats','line',5,'of the piste rated difficult on skiresort.com, the highest share of the four Savoie areas on this site','{}'::text[],'review','loader','stats.2.t'),
('area:tignes-val-disere','stats','line',6,'{{f:F000068}}',array['F000068']::text[],'review','loader','stats.3.v'),
('area:tignes-val-disere','stats','line',7,'for six days, adult, high season 2026/27; neither resort sells a week pass of its own','{}'::text[],'review','loader','stats.3.t'),
('area:tignes-val-disere','network','heading',0,'Two resorts over one ridge','{}'::text[],'review','loader','network.h2'),
('area:tignes-val-disere','network','para',0,'Tignes fills the upper bowl of its valley, from Les Brévières and Tignes 1800 near the Chevril dam up to Le Lac, Le Lavachet and Val Claret around the lake, with the Grande Motte glacier above them. Val d''Isère lies over the ridge to the east, strung out from La Daille through the village to Le Fornet, with Bellevarde and Solaise on either side of it. Lifts from both resorts reach the ridge between Tovière and Bellevarde, and in the map data a skier from Val Claret reaches La Daille in one lift ride and comes back in one.','{}'::text[],'review','loader','network.paras.0'),
('area:tignes-val-disere','network','para',1,'The link is broad. In the model no single lift closure separates the two resorts, and the worst closures add lift rides rather than cut journeys. Closing the Olympique or the Solaise gondola in the centre of Val d''Isère adds {{f:F000473}} lift rides in total across the journeys between sectors, and closing the Tommeuses chair, the main way up from La Daille to Tignes, adds {{f:F000475}}.',array['F000473','F000475']::text[],'review','loader','network.paras.1'),
('area:tignes-val-disere','network','para',2,'Le Fornet is the exception. Its lifts climb to the Pissaillas glacier, but the only lift out of the sector towards the rest of the area is the Leissières chair to Solaise. If it stops, Le Fornet can still be reached on skis but none of the other {{f:F000472|w}} sectors can be reached from it by lift.',array['F000472']::text[],'review','loader','network.paras.2'),
('area:tignes-val-disere','network','line',0,'{{m:all.val-claret.la-daille}} lift ride','{}'::text[],'review','loader','network.figs.0.v'),
('area:tignes-val-disere','network','line',1,'from Val Claret to La Daille, and {{m:all.la-daille.val-claret|w}} back','{}'::text[],'review','loader','network.figs.0.t'),
('area:tignes-val-disere','network','line',2,'{{m:all.brevieres.le-fornet}} lift rides','{}'::text[],'review','loader','network.figs.1.v'),
('area:tignes-val-disere','network','line',3,'from Les Brévières to Le Fornet, the longest crossing of the area, and {{m:all.le-fornet.brevieres|w}} back','{}'::text[],'review','loader','network.figs.1.t'),
('area:tignes-val-disere','network','line',4,'{{f:F000390}} minutes',array['F000390']::text[],'review','loader','network.figs.2.v'),
('area:tignes-val-disere','network','line',5,'on the Perce-Neige funicular, through the mountain from Val Claret towards the Grande Motte','{}'::text[],'review','loader','network.figs.2.t'),
('area:tignes-val-disere','network','line',6,'One chair','{}'::text[],'review','loader','network.figs.3.v'),
('area:tignes-val-disere','network','line',7,'links Le Fornet to the rest of the area: the Leissières, up to Solaise','{}'::text[],'review','loader','network.figs.3.t'),
('area:tignes-val-disere','network','line',8,'{{f:F000386}}',array['F000386']::text[],'review','loader','network.figs.4.v'),
('area:tignes-val-disere','network','line',9,'the old village of Tignes disappears under the Chevril reservoir','{}'::text[],'review','loader','network.figs.4.t'),
('area:tignes-val-disere','network','line',10,'{{f:F000388}}',array['F000388']::text[],'review','loader','network.figs.5.v'),
('area:tignes-val-disere','network','line',11,'Val d''Isère stages the Olympic downhill, super G and giant slalom on the Face de Bellevarde, and Tignes the freestyle','{}'::text[],'review','loader','network.figs.5.t'),
('area:tignes-val-disere','network','heading',1,'Explore the network','{}'::text[],'review','loader','network.mapTitle'),
('area:tignes-val-disere','network','caption',0,'Choose a starting point to see how many lift rides it takes to reach each other area, then limit the runs to see what stays within reach.','{}'::text[],'review','loader','network.mapHelp'),
('area:tignes-val-disere','network','caption',1,'Schematic, not to scale, with sectors moved apart for legibility. Built from OpenStreetMap lift and piste data (© OpenStreetMap contributors, snapshot 24 October 2026) with heights from the Copernicus 90 m elevation model. An orange link carries routes that no other link replaces when a single lift on it closes. Lift rides are the fewest needed between the lift bases of two areas. The model is being checked against the official 2026/27 piste map.','{}'::text[],'review','loader','network.caption'),
('area:tignes-val-disere','network','line',12,'Brévières','{}'::text[],'review','loader','sectors.0.short'),
('area:tignes-val-disere','network','line',13,'Le Lac','{}'::text[],'review','loader','sectors.1.short'),
('area:tignes-val-disere','network','line',14,'Tovière ridge','{}'::text[],'review','loader','mapNotes.0.text'),
('area:tignes-val-disere','network','line',15,'Bellevarde','{}'::text[],'review','loader','mapNotes.1.text'),
('area:tignes-val-disere','routes','heading',0,'Five sample days','{}'::text[],'review','loader','routes.h3'),
('area:tignes-val-disere','routes','line',0,'Each trip is counted in lift rides out and back, from the first lift base in each area, with the easiest grade of run that makes it in the map data. The counts start lower than the base table further down, which starts in the village. Time on the pistes, in queues and on foot is not included.','{}'::text[],'review','loader','routes.intro'),
('area:tignes-val-disere','routes','line',1,'Val Claret','{}'::text[],'review','loader','routes.rows.0.from'),
('area:tignes-val-disere','routes','line',2,'La Daille','{}'::text[],'review','loader','routes.rows.0.to'),
('area:tignes-val-disere','routes','line',3,'Green and blue','{}'::text[],'review','loader','routes.rows.0.grade'),
('area:tignes-val-disere','routes','note',0,'Out on the Fresse chair, back on the Tommeuses: one lift each way across the ridge.','{}'::text[],'review','loader','routes.rows.0.note'),
('area:tignes-val-disere','routes','line',4,'Val d''Isère','{}'::text[],'review','loader','routes.rows.1.from'),
('area:tignes-val-disere','routes','line',5,'Grande Motte','{}'::text[],'review','loader','routes.rows.1.to'),
('area:tignes-val-disere','routes','line',6,'Green and blue','{}'::text[],'review','loader','routes.rows.1.grade'),
('area:tignes-val-disere','routes','note',1,'Out by the Fontaine and Tommeuses chairs and the Perce-Neige funicular, home by the Fresse chair and the Funival.','{}'::text[],'review','loader','routes.rows.1.note'),
('area:tignes-val-disere','routes','line',7,'Tignes Le Lac','{}'::text[],'review','loader','routes.rows.2.from'),
('area:tignes-val-disere','routes','line',8,'Val d''Isère','{}'::text[],'review','loader','routes.rows.2.to'),
('area:tignes-val-disere','routes','line',9,'Black','{}'::text[],'review','loader','routes.rows.2.grade'),
('area:tignes-val-disere','routes','note',2,'The way out works on green and blue; coming back in the same number of rides needs a black, and otherwise takes {{m:red.val-disere.le-lac|w}}.','{}'::text[],'review','loader','routes.rows.2.note'),
('area:tignes-val-disere','routes','line',10,'Val Claret','{}'::text[],'review','loader','routes.rows.3.from'),
('area:tignes-val-disere','routes','line',11,'Le Fornet','{}'::text[],'review','loader','routes.rows.3.to'),
('area:tignes-val-disere','routes','line',12,'Red','{}'::text[],'review','loader','routes.rows.3.grade'),
('area:tignes-val-disere','routes','note',3,'On green and blue alone each way takes {{m:easy.val-claret.le-fornet|w}} lift rides.','{}'::text[],'review','loader','routes.rows.3.note'),
('area:tignes-val-disere','routes','line',13,'Les Brévières','{}'::text[],'review','loader','routes.rows.4.from'),
('area:tignes-val-disere','routes','line',14,'Le Fornet','{}'::text[],'review','loader','routes.rows.4.to'),
('area:tignes-val-disere','routes','line',15,'Black','{}'::text[],'review','loader','routes.rows.4.grade'),
('area:tignes-val-disere','routes','note',4,'The two ends of the area. Without blacks the way home takes {{m:red.le-fornet.brevieres|w}} lift rides, and on green and blue alone {{m:easy.le-fornet.brevieres|w}}.','{}'::text[],'review','loader','routes.rows.4.note'),
('area:tignes-val-disere','routes','note',5,'Most crossings between the two resorts work on green and blue. The hard grades matter on the way back into Tignes Le Lac and Les Brévières, where the fewest lift rides use a black run.','{}'::text[],'review','loader','routes.after'),
('area:tignes-val-disere','areas','heading',0,'The eight sectors compared','{}'::text[],'review','loader','areas.h2'),
('area:tignes-val-disere','areas','line',0,'Most of Tignes starts high, with Le Lac at {{f:F000420}} and Val Claret at {{f:F000424}}, while the lowest lifts of Les Brévières, La Daille and Val d''Isère start at {{f:F000416}}, {{f:F000432}} and {{f:F000436}}. Where a sector sits on the ridge decides how quickly the other resort can be reached.',array['F000416','F000420','F000424','F000432','F000436']::text[],'review','loader','areas.intro'),
('area:tignes-val-disere','areas','caption',0,'Sectors on the Tignes Val d''Isère pass','{}'::text[],'review','loader','areas.caption'),
('area:tignes-val-disere','areas','line',1,'Sector','{}'::text[],'review','loader','areas.nameLabel'),
('area:tignes-val-disere','areas','line',2,'Sectors','{}'::text[],'review','loader','areas.navLabel'),
('area:tignes-val-disere','areas','line',3,'Linked to Tignes Le Lac','{}'::text[],'review','loader','areas.rows.0.net'),
('area:tignes-val-disere','areas','note',0,'The lowest lift base in the area, below the Chevril dam.','{}'::text[],'review','loader','areas.rows.0.note'),
('area:tignes-val-disere','areas','line',4,'Linked, the centre of Tignes','{}'::text[],'review','loader','areas.rows.1.net'),
('area:tignes-val-disere','areas','note',1,'One lift ride from Val Claret, La Daille and Les Brévières.','{}'::text[],'review','loader','areas.rows.1.note'),
('area:tignes-val-disere','areas','line',5,'Linked, head of the Tignes valley','{}'::text[],'review','loader','areas.rows.2.net'),
('area:tignes-val-disere','areas','note',2,'Start of the Perce-Neige funicular, with the Tignes snowpark above.','{}'::text[],'review','loader','areas.rows.2.note'),
('area:tignes-val-disere','areas','line',6,'Linked by the Perce-Neige funicular','{}'::text[],'review','loader','areas.rows.3.net'),
('area:tignes-val-disere','areas','note',3,'The highest lifts in the area, most of them drags on the glacier.','{}'::text[],'review','loader','areas.rows.3.note'),
('area:tignes-val-disere','areas','line',7,'Linked to Tignes over the ridge','{}'::text[],'review','loader','areas.rows.4.net'),
('area:tignes-val-disere','areas','note',4,'The Funival and the Daille gondola climb to Bellevarde; La Folie Douce stands on the gondola.','{}'::text[],'review','loader','areas.rows.4.note'),
('area:tignes-val-disere','areas','line',8,'Linked, the centre of Val d''Isère','{}'::text[],'review','loader','areas.rows.5.net'),
('area:tignes-val-disere','areas','note',5,'Bellevarde and the Face, the Olympic downhill run.','{}'::text[],'review','loader','areas.rows.5.note'),
('area:tignes-val-disere','areas','line',9,'Linked by the Solaise gondola','{}'::text[],'review','loader','areas.rows.6.net'),
('area:tignes-val-disere','areas','note',6,'Ski Tranquille slow zones on the plateau.','{}'::text[],'review','loader','areas.rows.6.note'),
('area:tignes-val-disere','areas','line',10,'Linked to Solaise by one chair','{}'::text[],'review','loader','areas.rows.7.net'),
('area:tignes-val-disere','areas','note',7,'Reaches the Pissaillas glacier; the Leissières chair is its only lift out.','{}'::text[],'review','loader','areas.rows.7.note'),
('area:tignes-val-disere','areas','note',8,'From the OpenStreetMap lift and piste data (snapshot 24 October 2026) with heights from the Copernicus 90 m elevation model. Green and blue is the share of mapped piste length; drag lifts include platters and T bars as a share of the main lifts. Mapped piste is incomplete, so the shares are useful for comparing sectors but not as totals, and they are being checked against the official 2026/27 piste map.','{}'::text[],'review','loader','areas.note'),
('area:tignes-val-disere','terrain','heading',0,'Blacks on the way home','{}'::text[],'review','loader','terrain.h2'),
('area:tignes-val-disere','terrain','para',0,'The operator counts {{f:F000374}} runs: {{f:F000375}} green, {{f:F000376}} blue, {{f:F000377}} red and {{f:F000378}} black. skiresort.com measures {{f:F000084}} of the piste as easy, {{f:F000085}} as intermediate and {{f:F000086}} as difficult, the highest difficult share of the four Savoie areas on this site.',array['F000084','F000085','F000086','F000374','F000375','F000376','F000377','F000378']::text[],'review','loader','terrain.paras.0'),
('area:tignes-val-disere','terrain','para',1,'Green and blue reach every sector in the map data, but the way round can be long. Between the centres of the two resorts the easy routes cost at most one extra lift ride, while Solaise and Le Fornet are another matter: from Tignes Le Lac, Le Fornet takes {{m:easy.le-lac.le-fornet|w}} lift rides on green and blue against {{m:all.le-lac.le-fornet|w}} with every run allowed.','{}'::text[],'review','loader','terrain.paras.1'),
('area:tignes-val-disere','terrain','para',2,'Black runs matter more here than in the other big Savoie areas. Coming back into Tignes Le Lac and Les Brévières from Val d''Isère, the fewest lift rides use a black run, and staying on reds costs one more ride: from the village of Val d''Isère, Tignes Le Lac takes {{m:all.val-disere.le-lac|w}} lift rides with a black and {{m:red.val-disere.le-lac|w}} without.','{}'::text[],'review','loader','terrain.paras.2'),
('area:tignes-val-disere','terrain','para',3,'The steepest skiing is on the Val d''Isère side. The Face de Bellevarde, the Olympic downhill of {{f:F000388}}, runs from the Rocher de Bellevarde to the village, and the Oreiller-Killy red drops about {{f:F000392}} over just over {{f:F000391}} to La Daille. On the Tignes side the Grande Motte glacier runs fall about {{f:F000393}} to Val Claret when they are fully open.',array['F000388','F000391','F000392','F000393']::text[],'review','loader','terrain.paras.3'),
('area:tignes-val-disere','terrain','heading',1,'Lift rides between the areas, and the grade they need','{}'::text[],'review','loader','terrain.matrixTitle'),
('area:tignes-val-disere','terrain','note',0,'Rows are where the day starts, columns where it goes. Every cell can be reached on green and blue runs and shows the fewest lift rides on those runs; allowing reds and blacks shortens some journeys, as the explorer above shows. From the OpenStreetMap piste grades, snapshot 24 October 2026; untagged or wrongly tagged runs can distort the result, and each one is being checked against the official map.','{}'::text[],'review','loader','terrain.matrixNote'),
('area:tignes-val-disere','snow','heading',0,'Height holds the season','{}'::text[],'review','loader','snow.h2'),
('area:tignes-val-disere','snow','para',0,'Most of the skiing starts high. Tignes Le Lac and Val Claret have their lowest lifts at {{f:F000420}} and {{f:F000424}}, and on the elevation model the Grande Motte lifts start at {{f:F000428}} and climb to {{f:F000429}}. The low ground is limited to Les Brévières, La Daille and the village of Val d''Isère, whose lowest lifts start between {{f:F000416|n}} and {{f:F000436}}.',array['F000416','F000420','F000424','F000428','F000429','F000436']::text[],'review','loader','snow.paras.0'),
('area:tignes-val-disere','snow','para',1,'The weather model behind the snowfall figures covers the whole area with one grid cell, so it cannot tell Tignes from Val d''Isère, but it shows plainly what height does. In a typical season between 1991 and 2020, about {{f:F000105}} of snow fell at 1,600 m, {{f:F000478}} at 2,100 m and {{f:F000480}} at 2,600 m.',array['F000105','F000478','F000480']::text[],'review','loader','snow.paras.1'),
('area:tignes-val-disere','snow','para',2,'The lower slopes have lost the most. At 1,600 m the typical season fell from {{f:F000477}} in 1961 to 1990 to {{f:F000105}} in 1991 to 2020, and four of the last five seasons sat in the lowest third of the 76 year record. At 2,600 m the fall was smaller, from {{f:F000481}} to {{f:F000480}}, though three of the last five seasons were that poor.',array['F000105','F000477','F000480','F000481']::text[],'review','loader','snow.paras.2'),
('area:tignes-val-disere','snow','para',3,'Height still sets the calendar. Tignes opens on {{f:F000383|dm}}, a week before the link to Val d''Isère on {{f:F000384|dm}}, and the whole area runs to {{f:F000385|dm}}, later than the linked areas of Les 3 Vallées and Paradiski. The model gives snowfall rather than depth on the ground, and measured depths from weather stations are still being collected.',array['F000383','F000384','F000385']::text[],'review','loader','snow.paras.3'),
('area:tignes-val-disere','snow','heading',1,'Lift heights by sector','{}'::text[],'review','loader','snow.heightsTitle'),
('area:tignes-val-disere','snow','caption',0,'Lowest lift base to highest lift top in each sector. From OpenStreetMap lift positions and the Copernicus 90 m elevation model, which reads a little low on the highest summits.','{}'::text[],'review','loader','snow.heightsCaption'),
('area:tignes-val-disere','snow','heading',2,'Seasonal snowfall at three heights, 1950 to 2026','{}'::text[],'review','loader','snow.chartTitle'),
('area:tignes-val-disere','snow','caption',1,'Modelled snowfall from November to April, from the ERA5 reanalysis via the Open-Meteo historical weather API, for the grid cell at 45.5 N, 7.0 E adjusted to each height. Dots are single seasons; lines are 11 season running means. These are model values, not measurements on a piste.','{}'::text[],'review','loader','snow.chartCaption'),
('area:tignes-val-disere','snow','line',0,'Modelled snowfall from November to April. Dots are single seasons; lines are 11 season running means. Median 1991 to 2020: {{f:F000105}} at 1,600 m, {{f:F000478}} at 2,100 m, {{f:F000480}} at 2,600 m.',array['F000105','F000478','F000480']::text[],'review','loader','snow.chartDesc'),
('area:tignes-val-disere','snow','line',1,'<b>No conditions are reported here yet.</b> Tignes is due to open on {{f:F000383}} and the linked area on {{f:F000384}}. Until live data arrives, the official sources below give open lifts, pistes and forecasts.',array['F000383','F000384']::text[],'review','loader','snow.conditions.status'),
('area:tignes-val-disere','snow','line',2,'Lifts and pistes open','{}'::text[],'review','loader','snow.conditions.items.0.dt'),
('area:tignes-val-disere','snow','line',3,'<a href="https://en.tignes.net">Tignes</a> and <a href="https://www.valdisere.com/en/">Val d''Isère</a>','{}'::text[],'review','loader','snow.conditions.items.0.dd'),
('area:tignes-val-disere','snow','line',4,'Mountain forecast','{}'::text[],'review','loader','snow.conditions.items.1.dt'),
('area:tignes-val-disere','snow','line',5,'<a href="https://meteofrance.com/meteo-montagne">Météo-France mountain weather</a>','{}'::text[],'review','loader','snow.conditions.items.1.dd'),
('area:tignes-val-disere','snow','line',6,'Avalanche danger','{}'::text[],'review','loader','snow.conditions.items.2.dt'),
('area:tignes-val-disere','snow','line',7,'<a href="https://meteofrance.com/meteo-montagne">Météo-France bulletins</a> for the Savoie massifs, published daily in winter','{}'::text[],'review','loader','snow.conditions.items.2.dd'),
('area:tignes-val-disere','snow','line',8,'Terrain beyond the marked pistes is not controlled. The avalanche bulletin and local advice take precedence over anything on this page.','{}'::text[],'review','loader','snow.conditions.safety'),
('area:tignes-val-disere','pass','heading',0,'One pass for the week','{}'::text[],'review','loader','pass.h2'),
('area:tignes-val-disere','pass','para',0,'Neither resort sells a week pass of its own. Six days in high season cost {{f:F000068}} on the Tignes Val d''Isère pass, while the local passes of Tignes and Val d''Isère are sold by the half day or the day, at {{f:F000400}} and {{f:F000402}} for a day against {{f:F000067}} for the whole area.',array['F000067','F000068','F000400','F000402']::text[],'review','loader','pass.paras.0'),
('area:tignes-val-disere','pass','para',1,'For a week the choice is made, and the question becomes when to go. From {{f:F000404|dm}} to {{f:F000405|dm}} and from {{f:F000406|dm}} to {{f:F000407|dm}} a day on the whole area costs {{f:F000399}}, and a day on one resort {{f:F000401}}.',array['F000399','F000401','F000404','F000405','F000406','F000407']::text[],'review','loader','pass.paras.1'),
('area:tignes-val-disere','pass','caption',0,'Local day pass against the area day pass, adult, 2026/27','{}'::text[],'review','loader','pass.table.caption'),
('area:tignes-val-disere','pass','line',0,'Tignes, one day','{}'::text[],'review','loader','pass.table.rows.0.0'),
('area:tignes-val-disere','pass','line',1,'{{f:F000400}}',array['F000400']::text[],'review','loader','pass.table.rows.0.1'),
