('area:tignes-val-disere','pass','line',8,'Tignes, one day, early and late season','{}'::text[],'review','loader','pass.table.rows.2.0'),
('area:tignes-val-disere','pass','line',9,'{{f:F000401}}',array['F000401']::text[],'review','loader','pass.table.rows.2.1'),
