('area:tignes-val-disere','pass','note',0,'Sources: the <a href="https://www.tignes.co.uk/2026-2027-SkiPassPrices.pdf">Tignes Val d''Isère rate sheet</a> and <a href="https://guide-ski.fr/?p=170">Guide Ski for Tignes</a> and <a href="https://guide-ski.fr/?p=450">for Val d''Isère</a>.','{}'::text[],'review','loader','pass.table.note'),
('area:tignes-val-disere','pass','heading',1,'What the pass covers','{}'::text[],'review','loader','pass.coverageTitle'),
('area:tignes-val-disere','pass','line',16,'Linked both ways by lift and piste','{}'::text[],'review','loader','pass.coverage.0.label'),
('area:tignes-val-disere','pass','line',17,'Tignes: Les Brévières, Tignes 1800, Le Lac, Le Lavachet and Val Claret','{}'::text[],'review','loader','pass.coverage.0.items.0'),
('area:tignes-val-disere','pass','line',18,'The Grande Motte glacier','{}'::text[],'review','loader','pass.coverage.0.items.1'),
('area:tignes-val-disere','pass','line',19,'Val d''Isère: La Daille, the village, Solaise and Le Fornet','{}'::text[],'review','loader','pass.coverage.0.items.2'),
